pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {GameItems} from "../src/GameItems.sol";

contract InvMutTest is Test {
    GameItems c;
    function setUp() public { c = new GameItems(address(this), address(this)); }

    function testFuzz_property(bytes4 iface) public {
        bool ok;
        try c.supportsInterface(type(IERC1155MetadataURI).interfaceId) returns (bool res) {
            ok = res;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

interface IERC1155MetadataURI {
    function uri(uint256 id) external view returns (string memory);
}
